+fn justify(s: str, width: i64 where width >= 1) -> [str] {    let mut lines: [str] = []
+    let mut cur: [str] = []
+    let mut cur_chars = 0
+    let mut cur_len = 0
+    for w in str_split(s, " ") {
+        if len(w) == 0 {
+            continue
+        }
+        if len(cur) > 0 && cur_len + 1 + len(w) > width {
+            let mut line = ""
+            if len(cur) == 1 {
+                line = cur[0]
+                let mut k = len(cur[0])
+                while k < width {
+                    line = line + " "
+                    k = k + 1
+                }
+            } else {
+                let gaps = len(cur) - 1
+                let spaces = width - cur_chars
+                let base = spaces / gaps
+                let extra = spaces % gaps
+                for i in 0..len(cur) {
+                    line = line + cur[i]
+                    if i < gaps {
+                        let n = if i < extra { base + 1 } else { base }
+                        let mut k = 0
+                        while k < n {
+                            line = line + " "
+                            k = k + 1
+                        }
+                    }
+                }
+            }
+            lines = arr_push(lines, line)
+            cur = []
+            cur_chars = 0
+            cur_len = 0
+        }
+        if len(cur) == 0 {
+            cur_len = len(w)
+        } else {
+            cur_len = cur_len + 1 + len(w)
+        }
+        cur_chars = cur_chars + len(w)
+        cur = arr_push(cur, w)
+    }
+    if len(cur) > 0 {
+        lines = arr_push(lines, str_join(cur, " "))
+    }
+    lines}
